Global Anycast Load Balancer and API Gat.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Global Anycast Load Balancer and API Gateways container

Container_Boundary(global_anycast_load_balancer_and_api_gateways, "Global Anycast Load Balancer and API Gateways") {
    Component(Anycast_Load_Balancer, "Anycast Load Balancer", "Global Anycast DNS & Layer 4/7 Load Balancer", "Routes global ingress traffic to the nearest regional perimeter entry points.")
    Component(Kong_API_Gateway, "Kong API Gateway", "Kong", "Manages global ingress, TLS termination, and WAF security at the perimeter.")
}

Rel(Anycast_Load_Balancer, Kong_API_Gateway, "Routes ingress traffic", "HTTPS")

@enduml

